{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}

    # Required symbols and non-removable nodes form the mandatory slice.
    keep = set()
    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required:
            current = node
            while current is not None and current["id"] not in keep:
                keep.add(current["id"])
                parent_id = current.get("parent")
                current = by_id.get(parent_id)

    kept_nodes = [node["id"] for node in nodes if node["id"] in keep]
    removed_nodes = [node["id"] for node in nodes if node["id"] not in keep]
    return {
        "kept_nodes": kept_nodes,
        "removed_nodes": removed_nodes,
        "total_utility": sum(node.get("utility", 0) for node in nodes if node["id"] in keep),
    }
"}
